bool mc776_play_serverbound_use_item_encode(McPacket *packet, const Mc776PlayServerboundUseItem *value)
{
    if (packet == NULL || value == NULL) return false;
    if (!mc_packet_varint(packet, value->hand)) return false;
    if (!mc_packet_varint(packet, value->sequence)) return false;
    if (!mc_packet_float(packet, value->rotation.x)) return false;
    if (!mc_packet_float(packet, value->rotation.y)) return false;
    return !packet->failed;
}

bool mc776_play_serverbound_use_item_decode(McReader *reader, Mc776PlayServerboundUseItem *value)
{
    if (reader == NULL || value == NULL) return false;
    if (!mc_reader_varint(reader, &value->hand)) return false;
    if (!mc_reader_varint(reader, &value->sequence)) return false;
    if (!mc_reader_float(reader, &value->rotation.x)) return false;
    if (!mc_reader_float(reader, &value->rotation.y)) return false;
    return mc_reader_remaining(reader) == 0U;
}

bool mc776_play_serverbound_block_dig_encode(McPacket *packet, const Mc776PlayServerboundBlockDig *value)
{
    if (packet == NULL || value == NULL) return false;
    if (!mc_packet_varint(packet, value->status)) return false;
    if (!mc_packet_position(packet, 776, value->location)) return false;
    if (!mc_packet_i8(packet, value->face)) return false;
    if (!mc_packet_varint(packet, value->sequence)) return false;
    return !packet->failed;
}

bool mc776_play_serverbound_block_dig_decode(McReader *reader, Mc776PlayServerboundBlockDig *value)
{
    if (reader == NULL || value == NULL) return false;
    if (!mc_reader_varint(reader, &value->status)) return false;
    if (!mc_reader_position(reader, 776, &value->location)) return false;
    if (!mc_reader_i8(reader, &value->face)) return false;
    if (!mc_reader_varint(reader, &value->sequence)) return false;
    return mc_reader_remaining(reader) == 0U;
}
